<?php
require_once "../class/mysql.php";
require_once "../class/config.php";
require_once "../class/rbac.php";
header('Content-Type: application/json; charset=UTF-8');
$config=Configuration::getInstance();$database=Database::getInstance($config);$db=$database->getConnection();$rbacClass=new RBAC($db);
if(session_status()===PHP_SESSION_NONE)session_start();
$adminLanguage=$_COOKIE['admin_language']??$config->getConfig('defaultLanguage');$langFile="../lang/{$adminLanguage}.php";if(is_file($langFile))require $langFile;define('_lang',$config->getLang($adminLanguage));
function uomLang($k){return _lang[$k]??$k;} function uomOut($s,$m,$c=200){http_response_code($c);echo json_encode(['status'=>$s,'message'=>$m],JSON_UNESCAPED_UNICODE);exit;}
function uomRole($db,$id){$s=$db->prepare("SELECT id,all_rbac,company_id,unit_id FROM rbac WHERE id=? LIMIT 1");$s->bind_param('i',$id);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();return $r?:null;}
function uomCount($db,$table,$rid){$s=$db->prepare("SELECT COUNT(*) cnt FROM {$table} WHERE rbac_id=?");$s->bind_param('i',$rid);$s->execute();$n=(int)($s->get_result()->fetch_assoc()['cnt']??0);$s->close();return $n;}
function uomCompanyCount($db,$table,$cid){$s=$db->prepare("SELECT COUNT(*) cnt FROM {$table} p JOIN units u ON u.id=p.unit_id WHERE u.company_id=?");$s->bind_param('i',$cid);$s->execute();$n=(int)($s->get_result()->fetch_assoc()['cnt']??0);$s->close();return $n;}
function uomScope($db,$r){$a=uomCount($db,'admins',(int)$r['id']);$u=uomCount($db,'users',(int)$r['id']);if($a&&$u)return'shared';if($a)return'ipanel';if($u)return'iweb';$ca=uomCompanyCount($db,'admins',(int)$r['company_id']);$cu=uomCompanyCount($db,'users',(int)$r['company_id']);if($ca&&!$cu)return'ipanel';if($cu&&!$ca)return'iweb';if($ca&&$cu)return'shared';return'unassigned';}
function uomRows($db,$rid){$s=$db->prepare("SELECT COUNT(*) cnt FROM permissions_operation WHERE rbac_id=?");$s->bind_param('i',$rid);$s->execute();$n=(int)($s->get_result()->fetch_assoc()['cnt']??0);$s->close();return$n;}
function uomCatalog($db){$v=[];foreach([['p'=>'a','g'=>'admins_groups','pt'=>'admins_parts','s'=>'admins_subparts','pg'=>'admins_groups_id','sp'=>'admins_parts_id'],['p'=>'u','g'=>'users_groups','pt'=>'users_parts','s'=>'users_subparts','pg'=>'users_groups_id','sp'=>'users_parts_id']]as$c){$gp=[];$pp=[];$r=$db->query("SELECT id FROM {$c['g']}");while($r&&$x=$r->fetch_assoc()){$k=$c['p'].'g'.$x['id'];$v[$k]=['id'=>$k,'category'=>'group','prefix'=>$c['p'],'parent'=>null];$gp[(int)$x['id']]=$k;}$r=$db->query("SELECT id,{$c['pg']} gid FROM {$c['pt']}");while($r&&$x=$r->fetch_assoc()){$k=$c['p'].'p'.$x['id'];$v[$k]=['id'=>$k,'category'=>'part','prefix'=>$c['p'],'parent'=>$gp[(int)$x['gid']]??null];$pp[(int)$x['id']]=$k;}$r=$db->query("SELECT id,{$c['sp']} pid FROM {$c['s']}");while($r&&$x=$r->fetch_assoc()){$k=$c['p'].'s'.$x['id'];$v[$k]=['id'=>$k,'category'=>'subpart','prefix'=>$c['p'],'parent'=>$pp[(int)$x['pid']]??null];}}return$v;}
function uomNormalize($raw,$catalog,$scope){$d=json_decode((string)$raw,true);if(!is_array($d))$d=[];$sel=[];foreach($d as$i){$id=is_array($i)?trim((string)($i['id']??'')):trim((string)$i);if(!$id||!isset($catalog[$id]))continue;$n=$catalog[$id];if($scope==='ipanel'&&$n['prefix']!=='a')continue;if($scope==='iweb'&&$n['prefix']!=='u')continue;$sel[$id]=['id'=>$id,'category'=>$n['category']];$p=$n['parent'];while($p&&isset($catalog[$p])){$pn=$catalog[$p];$sel[$p]=['id'=>$p,'category'=>$pn['category']];$p=$pn['parent'];}}ksort($sel,SORT_NATURAL);return array_values($sel);}
if($_SERVER['REQUEST_METHOD']!=='POST')uomOut('error',uomLang('invalid_request'),405);$aid=(int)($_SESSION['admin_id']??0);if($aid<=0)uomOut('error',uomLang('operation_access_unauthorized'),401);$s=$db->prepare("SELECT status FROM admins WHERE id=?");$s->bind_param('i',$aid);$s->execute();$a=$s->get_result()->fetch_assoc();$s->close();if(!$a||strcasecmp($a['status'],'Active')!==0)uomOut('error',uomLang('operation_access_unauthorized'),401);if(!$rbacClass->checkPermissionPartByName('user_operation','access'))uomOut('error',uomLang('operation_access_forbidden'),403);
$csrf=(string)($_POST['csrf']??'');if(!$csrf||!hash_equals((string)($_SESSION['user_operation_csrf']??''),$csrf))uomOut('error',uomLang('operation_access_invalid_csrf'),403);$action=strtolower(trim((string)($_POST['action']??'')));$rid=(int)($_POST['rbac_id']??0);$role=uomRole($db,$rid);if(!$role)uomOut('error',uomLang('operation_access_role_invalid'),404);if((int)$role['all_rbac']===1)uomOut('error',uomLang('operation_access_protected_blocked'),403);
try{if($action==='save'){$rows=uomRows($db,$rid);$need=$rows?'edit_operation':'add_operation';if(!$rbacClass->checkPermissionOperationByName($need))uomOut('error',uomLang('operation_access_forbidden'),403);$parts=uomNormalize($_POST['parts_json']??'[]',uomCatalog($db),uomScope($db,$role));$ser=serialize($parts);$db->begin_transaction();try{if($rows){$s=$db->prepare("UPDATE permissions_operation SET parts=? WHERE rbac_id=?");$s->bind_param('si',$ser,$rid);}else{$ops=serialize([]);$status='Active';$s=$db->prepare("INSERT INTO permissions_operation(rbac_id,parts,operation,status) VALUES(?,?,?,?)");$s->bind_param('isss',$rid,$ser,$ops,$status);}$s->execute();$s->close();$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}uomOut('success',uomLang('operation_access_save_success'));}
if($action==='clear'){if(!$rbacClass->checkPermissionOperationByName('delete_operation'))uomOut('error',uomLang('operation_access_forbidden'),403);$empty=serialize([]);$s=$db->prepare("UPDATE permissions_operation SET parts=? WHERE rbac_id=?");$s->bind_param('si',$empty,$rid);$s->execute();$s->close();uomOut('success',uomLang('operation_access_clear_success'));}uomOut('error',uomLang('invalid_request'),400);}catch(Throwable$e){uomOut('error',uomLang('operation_access_unexpected_error'),500);}
